def parse(value, segment_bit_width, num_segments):
    segment_value_list = []
    assert len(value) == segment_bit_width * num_segments, f"incorrect length {len(value)}"
    print(len(value)/num_segments)
    for i in range(num_segments):
        offset = segment_bit_width*i
        segment_value_list.append(int(value[offset: offset + segment_bit_width],2))
    return segment_value_list, sum(segment_value_list)
    

